const r = $input.first().json;
const content = (r?.choices?.[0]?.message?.content || '').trim();
if (!content) throw new Error('IA sem resposta');
let out = { resumo: '', recomendacoes: [] };
try {
  const p = JSON.parse(content);
  out.resumo = (p.resumo || '').trim();
  out.recomendacoes = Array.isArray(p.recomendacoes) ? p.recomendacoes.filter((x) => typeof x === 'string' && x.trim()) : [];
} catch (e) { out.resumo = content; }
if (!out.resumo) throw new Error('IA sem resposta');
return out;
